import{MAX_INFLATED_BYTES}from"./limits.min.js";const B64="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";export function base64urlEncode(bytes){let out="";for(let i=0;i<bytes.length;i+=3){const b0=bytes[i];const b1=i+1<bytes.length?bytes[i+1]:null;const b2=i+2<bytes.length?bytes[i+2]:null;out+=B64[b0>>2];out+=B64[(b0&3)<<4|(b1===null?0:b1>>4)];if(b1!==null){out+=B64[(b1&15)<<2|(b2===null?0:b2>>6)]}if(b2!==null){out+=B64[b2&63]}}return out}export function base64urlDecode(str){const rev={};for(let i=0;i<B64.length;i++){rev[B64[i]]=i}const bytes=[];let buf=0;let bits=0;for(const c of str){const v=rev[c];if(v===void 0){throw new Error("base64url: invalid character")}buf=buf<<6|v;bits+=6;if(bits>=8){bits-=8;bytes.push(buf>>bits&255)}}return new Uint8Array(bytes)}const CRC8_SALT=[104,97,100];export function crc8Had(bytes){let crc=0;const feed=b=>{crc^=b&255;for(let i=0;i<8;i++){crc=crc&128?(crc<<1^7)&255:crc<<1&255}};for(const b of CRC8_SALT)feed(b);for(const b of bytes)feed(b);return crc&255}export function compressionAvailable(){return typeof CompressionStream!=="undefined"&&typeof DecompressionStream!=="undefined"}async function pipe(bytes,transform,max=Infinity){const reader=new Blob([bytes]).stream().pipeThrough(transform).getReader();const chunks=[];let total=0;for(;;){const{done,value}=await reader.read();if(done)break;total+=value.length;if(total>max){await reader.cancel();throw new Error("compress: decompressed payload too large")}chunks.push(value)}const out=new Uint8Array(total);let at=0;for(const c of chunks){out.set(c,at);at+=c.length}return out}export async function deflateRaw(bytes){return pipe(bytes,new CompressionStream("deflate-raw"))}export async function inflateRaw(bytes){return pipe(bytes,new DecompressionStream("deflate-raw"),MAX_INFLATED_BYTES)}
